-- Append to the rollback-only security suite. No real account is deleted.
reset role;
select set_config('aura.delete_uid',gen_random_uuid()::text,true),set_config('aura.delete_sid',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(current_setting('aura.delete_uid')::uuid,'delete-fixture@example.invalid',now(),false);
insert into auth.sessions(id,user_id,created_at,updated_at) values(current_setting('aura.delete_sid')::uuid,current_setting('aura.delete_uid')::uuid,now(),now());
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),current_setting('aura.delete_uid')::uuid,'totp','verified',now(),now());
insert into aura_private.licenses(email,status) values('delete-fixture@example.invalid','active');
insert into public.aura_members(clinic_id,email,role) values(current_setting('aura.clinic1')::uuid,'delete-fixture@example.invalid','manager');
select set_config('aura.delete_body',jsonb_build_object('email','delete-fixture@example.invalid','user_id',current_setting('aura.delete_uid'),'confirmation','delete-fixture@example.invalid')::text,true);
select set_config('aura.preserved_clinics',(select jsonb_agg(to_jsonb(c) order by id)::text from public.aura_clinics c where id in (current_setting('aura.clinic1')::uuid,current_setting('aura.clinic2')::uuid)),true);
create function pg_temp.admin_denied(body jsonb,wanted text default '22023') returns void language plpgsql as $$declare code text;begin begin perform public.aura_admin_rpc('delete_user',body);exception when others then get stacked diagnostics code=returned_sqlstate;end;perform pg_temp.check_ok(code=wanted,'delete_user denied with expected code');end$$;
set local role authenticated;
select pg_temp.as_user('2','aal2');
select pg_temp.admin_denied(current_setting('aura.delete_body')::jsonb,'42501');
select pg_temp.as_user('admin','aal1');
select pg_temp.admin_denied(current_setting('aura.delete_body')::jsonb,'42501');
select pg_temp.as_user('admin','aal2');
select pg_temp.admin_denied(jsonb_set(current_setting('aura.delete_body')::jsonb,'{confirmation}','"wrong@example.invalid"'));
select pg_temp.admin_denied(jsonb_set(current_setting('aura.delete_body')::jsonb,'{user_id}',to_jsonb(gen_random_uuid()::text)));
select pg_temp.admin_denied(jsonb_build_object('email','security-admin@example.invalid','user_id',current_setting('aura.admin'),'confirmation','security-admin@example.invalid'));
select pg_temp.admin_denied(jsonb_build_object('email','security-one@example.invalid','user_id',current_setting('aura.uid1'),'confirmation','security-one@example.invalid'));
select pg_temp.check_ok(exists(select 1 from jsonb_array_elements(public.aura_admin_rpc('list','{}')->'licenses') l where l->>'email'='delete-fixture@example.invalid' and l->>'user_id'=current_setting('aura.delete_uid') and l->>'delete_block_reason' is null),'eligible account listed with stable target ID');
reset role;
insert into aura_private.platform_admins(email) values('delete-fixture@example.invalid');
set local role authenticated;
select pg_temp.admin_denied(current_setting('aura.delete_body')::jsonb);
reset role;
delete from aura_private.platform_admins where email='delete-fixture@example.invalid';
insert into storage.buckets(id,name,public) values('delete-security-fixture','delete-security-fixture',false);
insert into storage.objects(bucket_id,name,owner,owner_id) values('delete-security-fixture','fixture.txt',current_setting('aura.delete_uid')::uuid,current_setting('aura.delete_uid'));
set local role authenticated;
select pg_temp.admin_denied(current_setting('aura.delete_body')::jsonb);
reset role;
update storage.objects set owner=null,owner_id=null where bucket_id='delete-security-fixture';
set local role authenticated;
select pg_temp.check_ok(public.aura_admin_rpc('delete_user',current_setting('aura.delete_body')::jsonb)->>'deleted'='true','eligible auth account deleted');
reset role;
select pg_temp.check_ok(not exists(select 1 from auth.users where id=current_setting('aura.delete_uid')::uuid),'auth user physically removed');
select pg_temp.check_ok(not exists(select 1 from auth.sessions where user_id=current_setting('aura.delete_uid')::uuid),'sessions removed');
select pg_temp.check_ok(not exists(select 1 from auth.mfa_factors where user_id=current_setting('aura.delete_uid')::uuid),'MFA factors cascade removed');
select pg_temp.check_ok(not exists(select 1 from aura_private.licenses where email='delete-fixture@example.invalid'),'license removed');
select pg_temp.check_ok(not exists(select 1 from public.aura_members where email='delete-fixture@example.invalid'),'clinic memberships removed');
select pg_temp.check_ok(exists(select 1 from aura_private.platform_audit where action='admin.delete_user' and target='delete-fixture@example.invalid'),'deletion recorded in protected audit');
select pg_temp.check_ok((select jsonb_agg(to_jsonb(c) order by id)::text from public.aura_clinics c where id in (current_setting('aura.clinic1')::uuid,current_setting('aura.clinic2')::uuid))=current_setting('aura.preserved_clinics'),'clinics and clinical history unchanged');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('aura.delete_uid'),'session_id',current_setting('aura.delete_sid'),'aal','aal2')::text,true);
select set_config('request.jwt.claim.sub',current_setting('aura.delete_uid'),true);
select pg_temp.denied('get',current_setting('aura.clinic1')::uuid,'{}');
select pg_temp.as_user('admin','aal2');
select pg_temp.admin_denied(current_setting('aura.delete_body')::jsonb);
reset role;
